volatile unsigned long pulseCount = 0;
unsigned long lastCalcTime = 0;
int currentRpm = 0;

void countPulse() {
  pulseCount++;
}

void setup() {
  Serial.begin(9600);
  pinMode(2, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(2), countPulse, FALLING);
}

void loop() {
  unsigned long now = millis();
  if (now - lastCalcTime >= 500) {
    detachInterrupt(digitalPinToInterrupt(2));
    currentRpm = (pulseCount * 60000) / ((now - lastCalcTime) * 1); // 1 slot
    pulseCount = 0;
    lastCalcTime = now;
    attachInterrupt(digitalPinToInterrupt(2), countPulse, FALLING);
    Serial.print("Motor Speed: "); Serial.print(currentRpm); Serial.println(" RPM");
  }
}
